// Parse LLM response
const llmResponse = JSON.parse($json.choices[0].message.content);
const extractData = $('Extract Inputs').first().json;
const currentContext = extractData.sharedContext;
const projectId = extractData.projectId;

// Merge context updates with safe defaults
const updatedContext = {
  ...currentContext,
  infrastructure_constraints: [
    ...(currentContext.infrastructure_constraints || []),
    ...(llmResponse.context_updates.infrastructure_constraints || [])
  ],
  identified_risks: [
    ...(currentContext.identified_risks || []),
    ...(llmResponse.context_updates.identified_risks || [])
  ],
  decision_rationale: {
    ...(currentContext.decision_rationale || {}),
    ...(llmResponse.context_updates.decision_rationale || {})
  },
  expert_recommendations: {
    ...(currentContext.expert_recommendations || {}),
    infrastructure_reviewer: llmResponse.analysis.executive_summary
  },
  approval_status: llmResponse.analysis.approval_status || 'pending'
};

return {
  json: {
    projectId,
    updatedContext,
    contextVersion: extractData.contextVersion + 1,
    analysis: llmResponse.analysis,
    markdownReport: llmResponse.markdown_report,
    recommendations: llmResponse.recommendations,
    approvalStatus: llmResponse.analysis.approval_status,
    requiredChanges: llmResponse.analysis.required_changes || []
  }
};
